def find_range(a, x):
    def first_at_least(v):
        lo, hi = 0, len(a)
        while lo < hi:
            mid = (lo + hi) // 2
            if a[mid] < v:
                lo = mid + 1
            else:
                hi = mid
        return lo
    lo = first_at_least(x)
    if lo == len(a) or a[lo] != x:
        return (-1, -1)
    return (lo, first_at_least(x + 1) - 1)

