def wait_for_higher(prices):
    out = [0] * len(prices)
    waiting = []
    for i, p in enumerate(prices):
        while waiting and prices[waiting[-1]] < p:
            j = waiting.pop()
            out[j] = i - j
        waiting.append(i)
    return out

